    ],
    whenNotToUse: [
      'Multi-select, search/typeahead, or rich option rendering — use the custom Select/Combobox',
      'A handful of mutually exclusive options where radios read better',
    ],
    antiPatterns: [
      {
        bad: '<NativeSelect options={oneHundredOptionsWithIcons} />',
        good: '<Combobox options={...} />',
        why: 'Native <option> cannot render icons or be searched; use a custom listbox for rich options',
      },
    ],
    related: [
      {
        name: 'Select',
        relationship: 'alternative',
        reason:
          'Custom-rendered listbox for richer options at the cost of native form/keyboard behavior',
      },
      {
        name: 'RadioCard',
        relationship: 'alternative',
        reason: 'Better for a small fixed set of mutually exclusive choices shown inline',
      },
    ],
    a11yRationale:
      'It is a real <select>, so the browser provides the combobox role, keyboard interaction, and announcement. aria-invalid is set when invalid; the placeholder is a disabled hidden first option so it shows but is not selectable. Where `appearance: base-select` is supported the option list is themed from CSS instead of the OS, and the browser still owns open/close, keyboard interaction, typeahead and form submission — nothing is re-implemented, so the accessibility story is identical on both paths.',
    flexibility: [
      {
        area: 'options',
        level: 'flexible',
        note: 'Pass an options array or raw <option> children',
      },
      {
        area: 'value',
        level: 'flexible',
        note: 'Controlled (value/onChange) or uncontrolled (defaultValue)',
      },
    ],
  },
}
